// ============================================================
// SUB: CEO BRIEFING
// Receives: { dashboardData, projectConfigs }
// Returns: { projectConfigs } — passed through to Project Warnings sub
// ============================================================

const input = $input.first().json;
const d = input.dashboardData;
const projectConfigs = input.projectConfigs; // Pass-through for next sub

const systemPrompt = `Bạn là AI phân tích kinh doanh cấp cao của Hecatech — công ty TikTok/Shopee commerce vận hành nhiều dự án trên các thị trường VN, Thái Lan, Malaysia, Philippines, Mỹ.

Nhiệm vụ: Tạo bản tin buổi sáng súc tích cho CEO. Phong cách: thẳng thắn, quyết đoán, tập trung hành động.

Các dự án:
- KTLVN: KTL Vietnam (flagship doanh số lớn nhất)
- XKMVN: Xịt Khử Mùi Vietnam
- TDCVN / KTMVN / MNVN: Các brand VN khác
- KTMR / SRMR: Thị trường đa quốc gia
- KTLTL / XKMTL: Thái Lan | XKMPH: Philippines | XKMMY: Malaysia`;

const userPrompt = `Data kinh doanh ngày ${d.reportDate}:
${JSON.stringify(d, null, 2)}

Tạo CEO Morning Briefing theo ĐÚNG format (tiếng Việt, dưới 380 từ):

📊 HECATECH MORNING BRIEFING — ${d.reportDate}

🏆 TỔNG QUAN
• Doanh số hôm qua: ${d.summary.totalDoanhSo}
• Lợi nhuận ròng MTD: ${d.tiktokMTD.loiNhuanRong} (${d.tiktokMTD.netProfitMargin})
• GMV TikTok MTD: ${d.tiktokMTD.gmv}
• Tình trạng: ✅ ${d.summary.green} xanh | 🟡 ${d.summary.yellow} vàng | 🔴 ${d.summary.red} đỏ

🔴 CẦN XỬ LÝ NGAY
[Phân tích từng dự án đỏ: số liệu thực + nguyên nhân có thể + 1 hành động cụ thể kèm tên người chịu trách nhiệm]
[Nếu không có: "Tất cả dự án đang đạt hoặc gần target 🎯"]

🟡 THEO DÕI
[Dự án vàng + lưu ý ngắn]
[Nếu không có: bỏ section]

✅ ĐANG THẮNG
[Top 2-3 dự án tốt nhất + 1 điểm nổi bật]

💡 TOP 3 VIỆC CẦN LÀM HÔM NAY
1. [Hành động — Người làm — Deadline]
2. [Hành động — Người làm — Deadline]
3. [Hành động — Người làm — Deadline]`;

return [{
  json: {
    projectConfigs, // Pass-through — Project Warnings sub will need this
    claudeRequest: {
      model: 'claude-sonnet-4-6',
      max_tokens: 1500,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }
  }
}];

const claudeResponse = $input.first().json;
const briefingText = claudeResponse?.content?.[0]?.text || '⚠️ Lỗi lấy dữ liệu từ AI.';

// Retrieve projectConfigs from the Build Request node (before Claude consumed it)
const projectConfigs = $('Build Claude CEO Request').first().json.projectConfigs;

return [{
  json: {
    projectConfigs, // Pass-through to Project Warnings sub
    larkMessage: { msg_type: 'text', content: { text: briefingText } }
  }
}];

// Return projectConfigs so Main Orchestrator can pass it to Project Warnings sub
const projectConfigs = $('Extract and Send CEO Lark').first().json.projectConfigs;
return [{ json: { projectConfigs, ceoBriefingStatus: 'sent' } }];
